"""Generate offline visual fixtures using only the production CSS contract."""
from pathlib import Path
import re
root=Path(__file__).resolve().parent
out=root/'mockups';out.mkdir(exist_ok=True)
paths=dict(re.findall(r"  (\w+): '([^']+)'",(root.parent/'src/ui/components/Icon.tsx').read_text()))
def icon(n):return f'<svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{paths[n]}"/></svg>'
def button(t,primary=False,extra=''):return f'<button class="btn{ " btn--primary" if primary else ""}" {extra}>{t}</button>'
def status(t,tone='info'):return f'<span class="badge badge--{tone}">{t}</span>'
def title(t,s):return f'<span class="cell-title">{t}</span><span class="cell-sub">{s}</span>'
def table(headers,rows,nums=(),caption='Records'):
 return '<div class="table-wrap"><table class="dt"><caption class="visually-hidden">'+caption+'</caption><thead><tr>'+''.join(f'<th scope="col" class="{"num" if i in nums else ""}">{h}</th>' for i,h in enumerate(headers))+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td data-label="{headers[i]}" class="{"dt-primary" if i==0 else "num" if i in nums else ""}">{v}</td>' for i,v in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
def kpis(items):return '<div class="kpis">'+''.join(f'<div class="kpi"><span class="kpi-label">{a}</span><span class="kpi-value">{b}</span><span class="kpi-sub">{c}</span></div>' for a,b,c in items)+'</div>'
def block(t,body,link='',full=False):return f'<section class="block{" block--full" if full else ""}"><div class="block-head"><h2>{t}</h2>{link}</div>{body}</section>'
def tabs(names):return '<div class="tabs" role="tablist">'+''.join(f'<button class="tab" role="tab" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-tab="{n.lower().replace(" ","-")}">{n}</button>' for i,n in enumerate(names))+'</div>'
def panel(name,body,visible=False):return f'<section class="stack tab-panel" id="{name}" role="tabpanel" {"" if visible else "hidden"}>{body}</section>'
def field(label,control):return f'<label class="field"><span class="field-label">{label}</span>{control}</label>'
def dialog(id,heading,body,large=False):return f'<dialog class="drawer{" drawer--lg" if large else ""}" id="{id}"><div class="drawer-inner"><header class="drawer-head"><h2>{heading}</h2><button class="icon-btn" aria-label="Close" data-close>{icon("close")}</button></header><div class="drawer-body stack">{body}</div></div></dialog>'
script='''<script>
const root=document.documentElement, q=new URLSearchParams(location.search);root.dataset.theme=q.get('theme')||'light';root.dataset.density=q.get('density')||'comfortable';
document.querySelectorAll('[data-theme-choice]').forEach(e=>{e.checked=e.value===root.dataset.theme;e.onchange=()=>root.dataset.theme=e.value});
document.querySelectorAll('[data-density-choice]').forEach(e=>{e.checked=e.value===root.dataset.density;e.onchange=()=>root.dataset.density=e.value});
document.querySelectorAll('[data-open]').forEach(e=>e.onclick=()=>document.getElementById(e.dataset.open).showModal());document.querySelectorAll('[data-close]').forEach(e=>e.onclick=()=>e.closest('dialog').close());
document.querySelectorAll('[data-nav-toggle]').forEach(e=>e.onclick=()=>{root.classList.toggle('nav-open');e.setAttribute('aria-expanded',root.classList.contains('nav-open'))});document.querySelector('.nav-scrim').onclick=()=>root.classList.remove('nav-open');
document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(t=>{t.setAttribute('aria-selected',t===e);t.tabIndex=t===e?0:-1;document.getElementById(t.dataset.tab).hidden=t!==e})});
document.querySelectorAll('[role=tablist]').forEach(list=>list.onkeydown=e=>{const tabs=[...list.children],i=tabs.indexOf(document.activeElement);if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const t=tabs[(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length];t.click();t.focus()}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.getElementById('search').showModal()}if(e.key==='Escape')root.classList.remove('nav-open')});
</script>'''
nav=[('home','Home','home'),('events','Events','calendar'),('finance','Requests & Finance','wallet'),('admin','Admin','shield')]
def shell(key,heading,sub,body,dialogs=''):
 links=''.join(f'<li><a class="nav-link" href="{k}.html" aria-label="{t}" title="{t}" {"aria-current=page" if key==k else ""}>{icon(i)}<span class="nav-label">{t}</span></a></li>' for k,t,i in nav)
 search='<button class="search-trigger" data-open="search" aria-label="Search"><span>'+icon('search')+'</span><span class="search-trigger-text">Search anything</span><kbd class="search-trigger-kbd">⌘ K</kbd></button>'
 return f'''<!doctype html><html lang="en" data-theme="light" data-role="director"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{heading} · CSEED design</title><link rel="stylesheet" href="../../src/styles/tokens.css"><link rel="stylesheet" href="../../src/styles/base.css"><link rel="stylesheet" href="../../src/styles/components.css"></head><body><a class="skip-link" href="#main">Skip to content</a><div class="app"><header class="topbar"><button class="icon-btn" data-nav-toggle aria-label="Menu" aria-expanded="false">{icon('menu')}</button><a class="wordmark" href="home.html">CSEED</a><button class="icon-btn" aria-label="Search" data-open="search">{icon('search')}</button></header><div class="nav-scrim"></div><nav class="sidebar" aria-label="Main"><a class="wordmark" href="home.html"><span class="wordmark-mark">C</span><span class="wordmark-text">CSEED<span class="wordmark-sub">Officer workspace</span></span></a>{search}<ul class="nav-list">{links}</ul><div class="sidebar-foot"><a class="nav-link" href="settings.html" aria-label="Settings" title="Settings" {"aria-current=page" if key=="settings" else ""}>{icon('settings')}<span class="nav-label">Settings</span></a><a class="user-chip" href="settings.html" aria-label="Alex Chen profile"><span class="avatar">AC</span><span class="user-chip-text"><span class="user-chip-name">Alex Chen</span><span class="user-chip-role">Director</span></span></a></div></nav><main class="main" id="main" tabindex="-1"><header class="page-header"><div><h1>{heading}</h1><p class="page-sub">{sub}</p></div></header><div class="stack">{body}</div><p class="preview-caption">CSEED · Visual prototype · Sample data</p></main></div>{dialogs}<dialog class="palette" id="search"><div class="palette-inner"><div class="palette-search">{icon('search')}<input class="palette-input" aria-label="Search workspace" placeholder="Search pages, events, requests…"><button class="icon-btn" data-close aria-label="Close search">{icon('close')}</button></div><div class="palette-results"><p class="palette-group-label">Pages</p>{''.join(f'<a class="palette-option" href="{k}.html">{t}</a>' for k,t,i in nav)}</div><div class="palette-foot muted small">Navigate to a page · Esc to close</div></div></dialog>{script}</body></html>'''
eventrows=[[title('Founder stories: building from zero','Oct 28, 2026 · The Nest'), 'Entrepreneurship','86','72','84%'],[title('Design for people','Oct 22, 2026 · ICICS 180'),'Design','64','51','80%'],[title('Fall venture night','Oct 15, 2026 · Sauder HA 098'),'Community','112','97','87%'],[title('Coffee & cofounders','Oct 9, 2026 · The Nest'),'Community','38','32','84%']]
events=table(['Event','Team','Registered','Attended','Check-in'],eventrows,(2,3,4),'Recent events')
budgetrows=[['Community','$4,000','$1,480','$2,520'],['Entrepreneurship','$5,500','$2,150','$3,350'],['Design','$3,000','$860','$2,140'],['Operations','$2,500','$590','$1,910']]
budget=table(['Team','Budget','Actual','Available'],budgetrows,(1,2,3),'Budget versus actual')
reqrows=[[title('Venture night catering','REQ-0042 · Maya Patel'),status('Pending','attention'),'Community','$286.40'],[title('Workshop materials','REQ-0041 · Jordan Lee'),status('Pending','attention'),'Design','$124.80'],[title('Speaker travel','REQ-0040 · Alex Chen'),status('Approved','positive'),'Entrepreneurship','$180.00'],[title('Name tags & signage','REQ-0039 · Maya Patel'),status('Settled','positive'),'Operations','$63.25']]
requests=table(['Request','Status','Team','Amount'],reqrows,(3,),'Purchase requests')
feed='<ol class="feed">'+''.join(f'<li class="feed-item"><span class="feed-text">{t}<span class="cell-sub">{s}</span></span><time class="feed-time">{d}</time></li>' for t,s,d in [('Maya submitted Venture night catering','Community · $286.40','24 min ago'),('Alex approved Speaker travel','Entrepreneurship · $180.00','2 hours ago'),('Jordan imported Design for people','64 registrations · 51 check-ins','Yesterday')])+'</ol>'
home=kpis([('Upcoming events','4','Next 30 days'),('Check-in rate','84%','Across 8 past events'),('Reflection rate','68%','Of checked-in guests'),('Budget available','$9,920','$5,080 spent of $15,000'),('Needs approval','2','$411.20 requested')])+'<div class="home-grid">'+block('Recent events',events,'<a class="small" href="events.html">All events →</a>',True)+block('Requests needing action','<ul class="list">'+''.join(f'<li class="list-row"><span class="list-main">{r[0]}</span><span class="list-side">{r[3]}{r[1]}</span></li>' for r in reqrows[:2])+'</ul>','<a class="small" href="finance.html">Review →</a>')+block('Budget vs actual',budget)+block('Activity',feed,full=True)+'</div>'
(out/'home.html').write_text(shell('home','Home','Your workspace at a glance · FY 2026–27',home))
chart='<figure class="chart"><svg viewBox="0 0 280 110" role="img" aria-label="Registrations grew from 12 to 86 over four weeks"><path class="chart-grid" d="M20 20H270M20 55H270M20 90H270"/><path class="chart-line" d="M20 80L65 72L110 66L155 44L200 39L245 20"/><text class="chart-axis" x="20" y="108">Oct 1</text><text class="chart-axis" x="220" y="108">Oct 28</text></svg><figcaption class="small muted">Registrations · 12 → 86 across October</figcaption></figure>'
detail='<div class="section-head"><h2>Founder stories</h2>'+status('Completed','positive')+'</div><p class="small muted">Oct 28 · The Nest<br>Hosted by Entrepreneurship</p>'+kpis([('Registered','86','Luma guest list'),('Attended','72','84% check-in')])+chart+'<h2>Guests</h2>'+table(['Guest','Status'],[[title('Jamie Wong','jamie@example.edu'),status('Checked in','positive')],[title('Sam Rivera','sam@example.edu'),status('Checked in','positive')]],caption='Event guests')
imp=field('Event name','<input class="input" value="Founder stories: building from zero">')+'<label class="dropzone"><strong>Choose a Luma CSV export</strong><span class="muted small">Guest list, check-ins or reflections · CSV files</span><input type="file" accept=".csv"></label><p class="notice notice--info">Check the preview before importing. Existing guests are matched by email.</p>'+button('Preview import',True)
ebody='<div class="toolbar"><div class="toolbar-main"><label class="toolbar-search"><span class="visually-hidden">Search events</span><input class="input" placeholder="Search events…"></label><div class="segmented"><button class="segment" aria-pressed="true">All events</button><button class="segment" aria-pressed="false">Upcoming</button></div></div>'+button(icon('upload')+' Import CSV',True,'data-open="import"')+'</div><div class="side-layout"><section class="stack"><div class="section-head"><h2>Fall term</h2><span class="small muted">8 events</span></div>'+events+button('Open event details',False,'data-open="event"')+'</section><aside class="side-panel stack">'+detail+'</aside></div>'
(out/'events.html').write_text(shell('events','Events','A clear picture of participation.',ebody,dialog('import','Import event data',imp)+dialog('event','Founder stories',detail)))
newreq='<p class="muted">Send a purchase request to your director for review.</p>'+field('Title','<input class="input" placeholder="What is this purchase for?">')+'<div class="grid-fields">'+field('Team','<select class="select"><option>Community</option><option>Design</option></select>')+field('Amount (CAD)','<input class="input" type="number" placeholder="0.00">')+'</div>'+field('Description','<textarea class="textarea" placeholder="Purpose and event details"></textarea>')+'<label class="dropzone">Receipt or quote<input type="file"></label><div class="form-actions">'+button('Submit request',True)+button('Cancel',False,'data-close')+'</div>'
reqdetail=status('Pending','attention')+'<h2>$286.40</h2><dl class="facts"><div><dt>Requested by</dt><dd>Maya Patel</dd></div><div><dt>Team</dt><dd>Community</dd></div><div><dt>Submitted</dt><dd>Oct 31, 2026</dd></div><div><dt>Request</dt><dd>REQ-0042</dd></div></dl><p>Catering for 40 attendees at Fall venture night. Includes vegetarian options.</p><h2>Receipt</h2><p class="file-name">catering-quote.pdf <span class="file-meta">184 KB</span></p><div class="action-panel"><h2>Director review</h2>'+field('Comment','<textarea class="textarea" placeholder="Add a note for Maya"></textarea>')+'<div class="action-row">'+button('Approve request',True)+button('Deny request',False)+'</div></div>'
fin=tabs(['Requests','Budgets','Reports','Periods'])+panel('requests','<div class="toolbar"><div class="chips"><button class="chip" aria-pressed="true">All <span class="chip-count">12</span></button><button class="chip">Pending <span class="chip-count">2</span></button><button class="chip">Approved</button><button class="chip">Settled</button></div>'+button('New request',True,'data-open="new-request"')+'</div>'+requests+'<div class="action-row">'+button('Review catering request',False,'data-open="request-detail"')+'<span class="small muted">2 requests await your approval</span></div>',True)+panel('budgets',kpis([('Allocated','$15,000','FY 2026–27'),('Spent','$5,080','Settled requests'),('Available','$9,920','Before pending requests')])+budget)+panel('reports','<div class="section-head"><h2>Statement of expenditure</h2>'+button('Export CSV')+'</div><p class="report-meta">FY 2026–27 · CAD · Cash basis · Oct 31, 2026</p>'+budget+'<p class="small muted">Total actual expenditure: $5,080.00</p>')+panel('periods',table(['Period','Status','Closed by'],[['October 2026',status('Open','positive'),'—'],['September 2026',status('Closed'),'Alex Chen · Oct 3'],['August 2026',status('Closed'),'Alex Chen · Sep 2']],caption='Financial periods'))
(out/'finance.html').write_text(shell('finance','Requests & Finance','Every request, from approval to settlement.',fin,dialog('new-request','New purchase request',newreq)+dialog('request-detail','Venture night catering',reqdetail)))
users=table(['Person','Role','Team','Status'],[[title('Alex Chen','alex@cseed.ca'),'Director','Operations',status('Active','positive')],[title('Maya Patel','maya@cseed.ca'),'Officer','Community',status('Active','positive')],[title('Jordan Lee','jordan@cseed.ca'),'Officer','Design',status('Active','positive')],[title('Taylor Brooks','taylor@cseed.ca'),'Officer','Entrepreneurship',status('Invited')]],caption='Workspace users')
admin=tabs(['Users','Tokens','Audit log'])+panel('users','<div class="toolbar"><label class="toolbar-search"><span class="visually-hidden">Find a person</span><input class="input" placeholder="Find a person…"></label>'+button('Invite user',True,'data-open="invite"')+'</div>'+users+'<p class="small muted">Directors manage budgets, approvals and workspace access.</p>',True)+panel('tokens','<div class="section-head"><h2>API tokens</h2>'+button('Create token',True,'data-open="token"')+'</div>'+table(['Name','Scope','Last used'],[[title('Luma import','cseed_••••7f2a'),'events:write','Oct 28, 2026'],[title('Finance export','cseed_••••2b91'),'finance:read','Oct 30, 2026']],caption='API tokens'))+panel('audit-log',table(['Action','Actor','Time'],[[title('Request approved','REQ-0040 · Speaker travel'),'Alex Chen','Oct 31 · 10:42'],[title('Guests imported','Design for people · 64 rows'),'Jordan Lee','Oct 30 · 16:12'],[title('Period closed','September 2026'),'Alex Chen','Oct 3 · 09:08']],caption='Audit log'))
(out/'admin.html').write_text(shell('admin','Admin','People, access and workspace history.',admin,dialog('invite','Invite a user',field('Email','<input type="email" class="input" placeholder="name@cseed.ca">')+field('Role','<select class="select"><option>Officer</option><option>Director</option></select>')+button('Send invitation',True))+dialog('token','Create API token',field('Name','<input class="input" placeholder="Integration name">')+'<p class="muted small">The secret is shown once after creation.</p>'+button('Create token',True))))
def choices(name,items):return '<div class="choice-row">'+''.join(f'<label class="choice"><input type="radio" name="{name}" value="{v}" data-{name}-choice {"checked" if i==0 else ""}><span class="choice-title">{t}</span><span class="choice-sub">{s}</span></label>' for i,(v,t,s) in enumerate(items))+'</div>'
settings='<div class="stack settings"><fieldset class="fieldset"><legend>Appearance</legend><p class="muted small">Choose how your workspace looks.</p>'+choices('theme',[('light','Light','A clear, white canvas'),('dark','Dark','Quiet, low-light surfaces'),('system','System','Follow your device')])+'</fieldset><fieldset class="fieldset"><legend>Density</legend><p class="muted small">Adjust the space between rows and blocks.</p>'+choices('density',[('comfortable','Comfortable','More space to read'),('compact','Compact','More information in view')])+'</fieldset><section class="section"><h2>Profile</h2><div class="profile"><span class="avatar avatar--lg">AC</span><dl class="facts"><div><dt>Name</dt><dd>Alex Chen</dd></div><div><dt>Email</dt><dd>alex@cseed.ca</dd></div><div><dt>Role</dt><dd>Director</dd></div><div><dt>Team</dt><dd>Operations</dd></div></dl></div><p class="small muted">Appearance and density changes are applied immediately on this preview.</p></section></div>'
(out/'settings.html').write_text(shell('settings','Settings','Make this workspace yours.',settings))
index='<p class="muted">Five representative screens. Each uses the production stylesheets directly. Choose a theme and width in your browser; Settings also previews density.</p>'+table(['Page','Light','Dark'],[[t,f'<a href="{k}.html">Open light →</a>',f'<a href="{k}.html?theme=dark">Open dark →</a>'] for k,t in [('home','Home'),('events','Events'),('finance','Requests & Finance'),('admin','Admin'),('settings','Settings')]],caption='Design mockups')
(out/'index.html').write_text(shell('index','Design review','CSEED officer dashboard · Version 2',index))
print('Generated six standalone HTML pages')
